head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교)  =====
scwin.INIT_ROWS = [
    { "col1": "col1_1", "col2": "col2_1", "col3": "col3_1", "col4": "col4_1" },
    { "col1": "col1_2", "col2": "col2_2", "col3": "col3_2", "col4": "col4_2" },
    { "col1": "col1_3", "col2": "col2_3", "col3": "col3_3", "col4": "col4_3" },
    { "col1": "col1_4", "col2": "col2_4", "col3": "col3_4", "col4": "col4_4" }
];

// 전체 Row 의 col1 ~ col4 값을 행별 한 줄로 출력
scwin.printRows = function (strPrefix) {
    var objDlt = $p.getComponentById("dlt_target");
    var arrAll = objDlt.getAllJSON();

    for (var i = 0; i < arrAll.length; i++) {
        var objRow = arrAll[i];
        scwin.setReturnValue(strPrefix + " row" + i
            + '  col1="' + objRow.col1 + '"'
            + '  col2="' + objRow.col2 + '"'
            + '  col3="' + objRow.col3 + '"'
            + '  col4="' + objRow.col4 + '"');
    }
};

scwin.btn_repro_onclick = function (e) {
    var objDlt = $p.getComponentById("dlt_target");

    // 1) 초기 데이터 재설정 (필터/정렬 해제됨)
    objDlt.setJSON(scwin.INIT_ROWS);

    // 2) col1 에 col1_2 / col1_4 만 보이도록 필터 적용 (필터뷰 2 행)
    objDlt.setColumnFilter({ type: 'row', colIndex: 'col1', key: "col1_2", condition: 'and' });
    objDlt.setColumnFilter({ type: 'row', colIndex: 'col1', key: "col1_4", condition: 'or' });

    scwin.printRows("[호출 전]");

    // 3) 필터뷰의 마지막 행(index 1) 을 대상으로 호출
    objDlt.rowMoveDownFiltered(1);

    scwin.setReturnValue("--- rowMoveDownFiltered(1) 호출 ---");
    scwin.printRows("[호출 후]");
};
